// Formatting Utilities - Formatlama Fonksiyonları

κλάση Formatting {
    στατικό συνάρτηση currency(amount, currency) {
        αν (currency == "TRY") {
            επιστροφή amount + " ₺";
        } αλλιώς {
            αν (currency == "USD") {
                επιστροφή "$" + amount;
            } αλλιώς {
                αν (currency == "EUR") {
                    επιστροφή "€" + amount;
                } αλλιώς {
                    επιστροφή amount + " " + currency;
                }
            }
        }
    }

    στατικό συνάρτηση date(date) {
        επιστροφή date;
    }

    στατικό συνάρτηση phone(phone) {
        // (555) 123-4567 formatı
        επιστροφή "(" + phone + ")";
    }

    στατικό συνάρτηση number(num) {
        // 1,234,567 formatı
        επιστροφή num;
    }
}

files.src/utils/validation.hudhud:
// Validation Utilities - Doğrulama Fonksiyonları

κλάση Validation {
    στατικό συνάρτηση email(email) {
        // Basit email αληθέςlama
        επιστροφή email.length > 5;
    }

    στατικό συνάρτηση password(password) {
        // Şifre en az 6 karakter olmalı
        επιστροφή password.length >= 6;
    }

    στατικό συνάρτηση price(price) {
        επιστροφή price > 0;
    }

    στατικό συνάρτηση phone(phone) {
        // Telefon numarası αληθέςlama
        επιστροφή phone.length == 10;
    }

    στατικό συνάρτηση required(value) {
        επιστροφή value.length > 0;
    }
}

